CREATE TABLE brands (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE models (code text PRIMARY KEY, brand_id text NOT NULL REFERENCES brands);
CREATE TABLE model_groups (code text PRIMARY KEY);
CREATE TABLE group_members (group_code text REFERENCES model_groups, model_code text REFERENCES models, PRIMARY KEY(group_code,model_code));
CREATE TABLE markets (code text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('country','group')));
CREATE TABLE market_aliases (alias text PRIMARY KEY, market_code text NOT NULL REFERENCES markets, review_status text NOT NULL CHECK(review_status='reviewed'));
CREATE TABLE categories (id text PRIMARY KEY CHECK(id ~ '^C(0[1-9]|10)$'), label text NOT NULL);
CREATE TABLE features (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category_id text NOT NULL REFERENCES categories, name text NOT NULL);
CREATE TABLE attributes (id text PRIMARY KEY, category_id text NOT NULL REFERENCES categories, value_type text NOT NULL CHECK(value_type IN ('number','text','boolean','range')), unit text);
CREATE TABLE variants (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, model_code text NOT NULL REFERENCES models, label text NOT NULL, powertrain text, UNIQUE(id,model_code));
CREATE TABLE source_trim_labels (label text PRIMARY KEY);
CREATE TABLE datasets (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, namespace text UNIQUE NOT NULL, evidence_kind text NOT NULL CHECK(evidence_kind IN ('published_specification','customer_statement','configurator_session','sales_aggregate','study_aggregate','generated_scenario','derived_assessment')));
CREATE TABLE source_assets (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, sha256 text UNIQUE NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'), original_filename text NOT NULL, original_location text NOT NULL, storage_path text NOT NULL);
CREATE TABLE dataset_versions (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, dataset_id bigint NOT NULL REFERENCES datasets, asset_id bigint NOT NULL REFERENCES source_assets, data_origin text NOT NULL CHECK(data_origin IN ('observed','synthetic','unknown')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(dataset_id,asset_id), UNIQUE(id,data_origin));
CREATE TABLE scenarios (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, version_id bigint NOT NULL UNIQUE, data_origin text NOT NULL DEFAULT 'synthetic' CHECK(data_origin='synthetic'), assumptions jsonb NOT NULL CHECK(jsonb_typeof(assumptions)='object'), FOREIGN KEY(version_id,data_origin) REFERENCES dataset_versions(id,data_origin), UNIQUE(id,version_id));
CREATE TABLE source_records (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, version_id bigint NOT NULL REFERENCES dataset_versions, record_number integer NOT NULL CHECK(record_number>0), external_id text, raw_payload jsonb NOT NULL CHECK(jsonb_typeof(raw_payload)='object'), review_status text NOT NULL DEFAULT 'unreviewed' CHECK(review_status IN ('unreviewed','reviewed','rejected')), scope_layer text CHECK(scope_layer IN ('fixed','variable','hypothetical')), UNIQUE(version_id,record_number), UNIQUE(version_id,external_id), UNIQUE(id,version_id));
CREATE TABLE evidence_locations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, record_id bigint NOT NULL REFERENCES source_records, page integer CHECK(page>0), sheet text, cell_range text, row_number integer CHECK(row_number>0), CHECK(page IS NOT NULL OR sheet IS NOT NULL OR row_number IS NOT NULL));
CREATE TABLE ingestion_runs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, asset_id bigint NOT NULL REFERENCES source_assets, version_id bigint REFERENCES dataset_versions, parser_version text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL CHECK(status IN ('running','succeeded','quarantined')), report jsonb NOT NULL DEFAULT '{}');
CREATE TABLE validation_issues (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, run_id bigint NOT NULL REFERENCES ingestion_runs, record_id bigint NOT NULL REFERENCES source_records, code text NOT NULL, reason text NOT NULL);
CREATE TABLE configurator_sessions (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, version_id bigint NOT NULL, source_record_id bigint NOT NULL UNIQUE, scenario_id bigint NOT NULL, data_origin text NOT NULL DEFAULT 'synthetic' CHECK(data_origin='synthetic'), external_id text NOT NULL, source_timestamp timestamptz NOT NULL, raw_timestamp text NOT NULL, model_code text NOT NULL REFERENCES models, variant_id bigint, market_code text NOT NULL REFERENCES markets, raw_region text NOT NULL, trim_label text NOT NULL REFERENCES source_trim_labels, final_stage text NOT NULL, package_attach_success boolean NOT NULL, raw_synthetic_score numeric NOT NULL CHECK(raw_synthetic_score::text NOT IN ('NaN','Infinity','-Infinity')), raw_viewed jsonb NOT NULL CHECK(jsonb_typeof(raw_viewed)='array'), raw_selected jsonb NOT NULL CHECK(jsonb_typeof(raw_selected)='array'), UNIQUE(version_id,external_id), FOREIGN KEY(source_record_id,version_id) REFERENCES source_records(id,version_id), FOREIGN KEY(scenario_id,version_id) REFERENCES scenarios(id,version_id), FOREIGN KEY(version_id,data_origin) REFERENCES dataset_versions(id,data_origin), FOREIGN KEY(variant_id,model_code) REFERENCES variants(id,model_code));
CREATE TABLE reviewed_option_mappings (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, model_code text NOT NULL REFERENCES models, variant_id bigint, market_code text NOT NULL REFERENCES markets, edition text NOT NULL, option_code text NOT NULL, feature_id bigint NOT NULL REFERENCES features, evidence_location_id bigint NOT NULL REFERENCES evidence_locations, reviewer text NOT NULL, reviewed_at timestamptz NOT NULL, FOREIGN KEY(variant_id,model_code) REFERENCES variants(id,model_code));
CREATE TABLE configurator_session_options (session_id bigint NOT NULL REFERENCES configurator_sessions, option_code text NOT NULL CHECK(option_code ~ '^SA[A-Za-z0-9]+$'), viewed boolean NOT NULL DEFAULT true CHECK(viewed), selected boolean NOT NULL, mapping_status text NOT NULL DEFAULT 'unresolved' CHECK(mapping_status='unresolved'), PRIMARY KEY(session_id,option_code));
CREATE INDEX session_cohort ON configurator_sessions(version_id,model_code,market_code,source_timestamp);
